function getBiggestThree(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const top = [];

  function add(sum) {
    if (top.includes(sum)) return;
    top.push(sum);
    top.sort((a, b) => b - a);
    if (top.length > 3) top.pop();
  }

  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      add(grid[r][c]);
      for (let k = 1; r + 2 * k < m && c - k >= 0 && c + k < n; k++) {
        let sum = 0;
        for (let t = 0; t < k; t++) {
          sum += grid[r + t][c + t];
          sum += grid[r + k + t][c + k - t];
          sum += grid[r + 2 * k - t][c - t];
          sum += grid[r + k - t][c - k + t];
        }
        add(sum);
      }
    }
  }
  return top;
}

