function getBiggestThree(grid) {
  const m = grid.length, n = grid[0].length;
  const sums = new Set();
  for (let cr = 0; cr < m; cr++) {
    for (let cc = 0; cc < n; cc++) {
      for (let k = 0; cr - k >= 0 && cr + k < m && cc - k >= 0 && cc + k < n; k++) {
        let total = 0;
        for (let i = 0; i < m; i++)
          for (let j = 0; j < n; j++)
            if (Math.abs(i - cr) + Math.abs(j - cc) === k) total += grid[i][j];
        sums.add(total);
      }
    }
  }
  return [...sums].sort((a, b) => b - a).slice(0, 3);
}

